create or replace function maths._preview_session(p_uid uuid,p_ids text[],p_mode text,p_title text,p_params jsonb default '{}'::jsonb,p_force_memory_reveal boolean default false) returns jsonb language plpgsql volatile security definer set search_path=pg_catalog,public,maths as $$ declare sid text:='local-'||md5(p_uid::text||clock_timestamp()::text||coalesce(array_to_string(p_ids,','),'')); begin if coalesce(array_length(p_ids,1),0)=0 then return jsonb_build_object('ok',false,'message','No eligible questions found.','localSafe',true); end if; return jsonb_build_object('ok',true,'localSafe',true,'sessionId',sid,'mode',p_mode,'title',p_title,'currentIndex',0,'completed',false,'target',array_length(p_ids,1),'params',coalesce(p_params,'{}'::jsonb),'questions',maths._render_questions(p_uid,p_ids,p_force_memory_reveal),'attempts','{}'::jsonb,'flags','{}'::jsonb); end $$;
create or replace function public.maths_get_local_safe_start(p_start_rpc text,p_args jsonb default '{}'::jsonb) returns jsonb language plpgsql volatile security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); name_ text:=lower(coalesce(p_start_rpc,'')); args jsonb:=coalesce(p_args,'{}'::jsonb); ids text[]; base text[]; recent text[]; extra text[]; day_ int:=maths._study_day(); count_ int; kind_ text; scope_ text; chapter_ text; topic_ text; group_ text; type_ text; skill_ text; mode_ text; set_id_ text; title_ text; out_ jsonb; rendered_ jsonb; begin
 if name_='maths_start_daily' then count_:=greatest(1,coalesce(nullif(maths._setting('daily_chapter_size','25'),'')::int,25)); ids:=maths._select_daily_ids(uid,day_,count_,array[]::text[]); return maths._preview_session(uid,ids,'daily','Day '||day_||' · Mixed Revision',jsonb_build_object('planDay',day_,'planChapter','Mixed Revision','dailyVersion','v20'),false);
 elsif name_='maths_start_practice_more' then count_:=greatest(1,least(coalesce((args->>'p_count')::int,nullif(maths._setting('practice_more_size','20'),'')::int,20),100)); select coalesce(array_agg(distinct sq.question_id),array[]::text[]) into recent from maths.session_questions sq join(select session_id from maths.sessions where user_id=uid and lower(coalesce(mode,'')) in('daily','practice_more') order by updated_at desc nulls last limit 2)s using(session_id); ids:=maths._select_daily_ids(uid,day_,count_,recent); if coalesce(array_length(ids,1),0)<count_ then extra:=maths._select_daily_ids(uid,day_,count_-coalesce(array_length(ids,1),0),ids); ids:=ids||extra; end if; return maths._preview_session(uid,ids,'practice_more','Practice More · Mixed Revision',jsonb_build_object('planDay',day_,'practiceMore',true),false);
 elsif name_='maths_start_focused_practice' then scope_:=coalesce(args->>'p_scope','all'); kind_:=coalesce(args->>'p_kind','random'); chapter_:=nullif(args->>'p_chapter',''); topic_:=nullif(args->>'p_topic',''); group_:=nullif(args->>'p_group',''); count_:=greatest(1,least(coalesce((args->>'p_count')::int,20),100)); base:=maths._question_ids(uid,scope_,chapter_,topic_,group_); ids:=maths._select_by_kind(uid,base,kind_,count_); title_:=coalesce(topic_,chapter_,initcap(group_),case when lower(scope_)='new_practice' then 'New Practice' when lower(scope_)='starred' then 'Starred Revision' when lower(scope_)='generated' then 'Generated Practice' else 'Maths Practice' end)||' · '||initcap(replace(kind_,'_',' ')); return maths._preview_session(uid,ids,'maths_'||lower(kind_),title_,args,false);
 elsif name_='maths_start_mock_practice' then kind_:=coalesce(args->>'p_kind','random'); chapter_:=nullif(args->>'p_chapter',''); count_:=greatest(1,least(coalesce((args->>'p_count')::int,20),100)); select coalesce(array_agg(question_id),array[]::text[]) into base from maths._user_runtime(uid) where runtime_active and in_mock and (chapter_ is null or maths._norm(chapter)=maths._norm(chapter_)); ids:=maths._select_by_kind(uid,base,kind_,count_); return maths._preview_session(uid,ids,'mock_questions','Mocks · '||coalesce(chapter_,'All')||' · '||initcap(kind_),args,false);
 elsif name_='maths_start_formula_revision' then kind_:=coalesce(args->>'p_kind','all'); chapter_:=nullif(args->>'p_chapter',''); count_:=greatest(1,least(coalesce((args->>'p_count')::int,20),100)); select coalesce(array_agg(question_id),array[]::text[]) into base from maths._user_runtime(uid) where runtime_active and in_formula_revision and (chapter_ is null or maths._norm(chapter)=maths._norm(chapter_)); ids:=maths._select_by_kind(uid,base,kind_,count_); return maths._preview_session(uid,ids,'formula_revision','Formula Revision · '||coalesce(chapter_,'All')||' · '||initcap(kind_),args,false);
 elsif name_='maths_start_concepts' then kind_:=coalesce(args->>'p_kind','random'); chapter_:=nullif(args->>'p_chapter',''); topic_:=nullif(args->>'p_topic',''); count_:=greatest(1,least(coalesce((args->>'p_count')::int,20),100)); select coalesce(array_agg(r.question_id),array[]::text[]) into base from maths._user_runtime(uid) r join maths.concept_membership c on c.user_id=uid and c.question_id=r.question_id and c.active where r.runtime_active and (chapter_ is null or maths._norm(r.chapter)=maths._norm(chapter_)) and (topic_ is null or maths._norm(r.major_topic)=maths._norm(topic_)); ids:=maths._select_by_kind(uid,base,kind_,count_); return maths._preview_session(uid,ids,'concept_saved','Concepts · '||coalesce(topic_,chapter_,'All')||' · '||initcap(kind_),args,false);
 elsif name_='maths_start_demand_set' then set_id_:=args->>'p_set_id'; kind_:=coalesce(args->>'p_kind','random'); count_:=greatest(1,least(coalesce((args->>'p_count')::int,20),100)); select set_name into title_ from maths.practice_sets where user_id=uid and set_id=set_id_ and lower(coalesce(status,'active'))<>'inactive'; if not found then raise exception 'Demand set not found'; end if; select coalesce(array_agg(i.question_id order by i.sequence),array[]::text[]) into base from maths.practice_set_items i join maths.runtime_questions q on q.question_id=i.question_id and q.runtime_active where i.set_id=set_id_; ids:=maths._select_by_kind(uid,base,kind_,count_); return maths._preview_session(uid,ids,'demand_set',title_||' · '||initcap(kind_),args,false);
 elsif name_='maths_start_calculation' then mode_:=lower(coalesce(args->>'p_mode','mixed')); type_:=nullif(args->>'p_type',''); skill_:=nullif(args->>'p_skill',''); count_:=greatest(1,least(coalesce((args->>'p_count')::int,20),100)); with c as(select r.question_id,r.profile_last_result,r.difficult,r.last_response_sec,r.state_attempts,maths._calc_type(q) typ,maths._norm(coalesce(q.topic,q.subtopic,'Mixed')) skill from maths._user_runtime(uid) r join maths.runtime_questions q using(question_id) where r.runtime_active and (r.bank_calculation or r.in_calc_set) and (maths._calc_type(q)<>'MEMORY' or maths._calc_recall_eligible(q))) select coalesce(array_agg(question_id),array[]::text[]) into base from c where (type_ is null or typ=upper(type_)) and (skill_ is null or skill=maths._norm(skill_)) and (mode_<>'recall' or typ='MEMORY'); if mode_ in('weak','slow') then select coalesce(array_agg(x.question_id),array[]::text[]) into ids from(select r.question_id from maths._user_runtime(uid) r where r.question_id=any(base) order by (r.profile_last_result='wrong') desc,r.difficult desc,(r.last_response_sec>=8) desc,(r.state_attempts=0) desc,r.last_response_sec desc limit count_)x; elsif mode_='all' then ids:=base; else select coalesce(array_agg(x),array[]::text[]) into ids from(select unnest(base)x order by random() limit count_)z; end if; title_:='Calculation Training · '||case when mode_='recall' then 'Recall' when mode_ in('weak','slow') then 'Weak & Slow' when mode_='all' then 'All' else 'Mixed Practice' end; out_:=maths._preview_session(uid,ids,'calculation_speed',title_,args,mode_='recall'); if mode_='mixed' and coalesce(out_->>'sessionId','')<>'' then select jsonb_agg(case when maths._calc_type(q)='MEMORY' then (e-'options'-'correctOption'-'answerMode'-'variantType')||jsonb_build_object('options','[]'::jsonb,'correctOption','','answerMode','REVEAL','variantType','CALC_RECALL') else e end order by ord) into rendered_ from jsonb_array_elements(out_->'questions') with ordinality z(e,ord) join maths.runtime_questions q on q.question_id=e->>'questionId'; out_:=jsonb_set(out_,'{questions}',coalesce(rendered_,'[]'::jsonb)); end if; return out_;
 else raise exception 'Unsupported local-safe start RPC'; end if;
end $$;
revoke all on function maths._preview_session(uuid,text[],text,text,jsonb,boolean) from public,anon,authenticated;
revoke all on function public.maths_get_local_safe_start(text,jsonb) from public,anon; grant execute on function public.maths_get_local_safe_start(text,jsonb) to authenticated;


